import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"43、【夬】 乾下兌上","description":"橫渠易說 - 43、【夬】 乾下兌上","frontmatter":{"title":"43、【夬】 乾下兌上","description":"橫渠易說 - 43、【夬】 乾下兌上"},"headers":[],"relativePath":"classics/hengqu/045.md","filePath":"classics/hengqu/045.md"}'),l={name:"classics/hengqu/045.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_43、【夬】-乾下兌上" tabindex="-1">43、【夬】 乾下兌上 <a class="header-anchor" href="#_43、【夬】-乾下兌上" aria-label="Permalink to “43、【夬】 乾下兌上”">​</a></h1><p>益而不已必決，故受之以夬。</p><h3 id="彖曰-夬-決也-剛決柔也-健而說-決而和。-揚於王庭-柔乘五剛也-孚號有厲-其危乃光也。-告自邑-不利即戎-所尚乃窮也-利有攸往-剛長乃終也。" tabindex="-1">彖曰：夬，決也，剛決柔也，健而說，決而和。“揚於王庭”，柔乘五剛也；“孚號有厲”，其危乃光也。“告自邑，不利即戎”所尚乃窮也；“利有攸往”，剛長乃終也。 <a class="header-anchor" href="#彖曰-夬-決也-剛決柔也-健而說-決而和。-揚於王庭-柔乘五剛也-孚號有厲-其危乃光也。-告自邑-不利即戎-所尚乃窮也-利有攸往-剛長乃終也。" aria-label="Permalink to “彖曰：夬，決也，剛決柔也，健而說，決而和。“揚於王庭”，柔乘五剛也；“孚號有厲”，其危乃光也。“告自邑，不利即戎”所尚乃窮也；“利有攸往”，剛長乃終也。”">​</a></h3><p>不可以必勝而忽慢，故能矜慎則愈光也。 除惡務本，故利有所進而後為德乃終。</p><h3 id="象曰-澤上於天-夬-君子以施祿及下-居德則忌。" tabindex="-1">象曰：澤上於天，夬，君子以施祿及下，居德則忌。 <a class="header-anchor" href="#象曰-澤上於天-夬-君子以施祿及下-居德則忌。" aria-label="Permalink to “象曰：澤上於天，夬，君子以施祿及下，居德則忌。”">​</a></h3><p>君子道長，故非德之禁可以必行，然不可恃令之行，無恩以及下也。</p><h3 id="初九-壯於前趾-往不勝為咎。-象曰-不勝而往-咎也。" tabindex="-1">初九，壯於前趾，往不勝為咎。 象曰：不勝而往，咎也。 <a class="header-anchor" href="#初九-壯於前趾-往不勝為咎。-象曰-不勝而往-咎也。" aria-label="Permalink to “初九，壯於前趾，往不勝為咎。 象曰：不勝而往，咎也。”">​</a></h3><p>言能慮勝而往則無咎。</p><h3 id="九二-惕號-莫夜有戎勿恤。-象曰-有戎勿恤-得中道也。" tabindex="-1">九二，惕號，莫夜有戎勿恤。 象曰：“有戎勿恤”，得中道也。 <a class="header-anchor" href="#九二-惕號-莫夜有戎勿恤。-象曰-有戎勿恤-得中道也。" aria-label="Permalink to “九二，惕號，莫夜有戎勿恤。 象曰：“有戎勿恤”，得中道也。”">​</a></h3><p>警懼申號，能孚號而有厲也。以必勝之剛，決至危之柔，能自危慮，雖有戎何恤!能得中道，故剛而不暴。</p><h3 id="九三-壯於頄-有兇。君子夬夬-獨行遇雨若濡-有慍-無咎。-象曰-君子夬夬-終無咎也。" tabindex="-1">九三，壯於頄，有兇。君子夬夬，獨行遇雨若濡，有慍，無咎。 象曰：“君子夬夬”，終無咎也。 <a class="header-anchor" href="#九三-壯於頄-有兇。君子夬夬-獨行遇雨若濡-有慍-無咎。-象曰-君子夬夬-終無咎也。" aria-label="Permalink to “九三，壯於頄，有兇。君子夬夬，獨行遇雨若濡，有慍，無咎。 象曰：“君子夬夬”，終無咎也。”">​</a></h3><p>九三以陽居陽，進決於上，是壯於頄也。不得中道，過壯或兇，故曰“有兇”。君子明於事幾，能夬於用夬，進而緩之以善其終，不假用眾，故曰“獨行”；使之悅從，故曰“遇雨若濡”。君子之心終［無繫累］，故必有慍。雖其有慍，於正無害，故［曰］“無咎”，［故］君子之道綽然餘裕，終不為咎也。</p><h3 id="九四-臀無膚-其行次且-牽羊悔亡-聞言不信。-象曰-其行次且-位不當也。-聞言不信-聰不明也。" tabindex="-1">九四，臀無膚，其行次且，牽羊悔亡，聞言不信。 象曰：“其行次且”，位不當也。“聞言不信”，聰不明也。 <a class="header-anchor" href="#九四-臀無膚-其行次且-牽羊悔亡-聞言不信。-象曰-其行次且-位不當也。-聞言不信-聰不明也。" aria-label="Permalink to “九四，臀無膚，其行次且，牽羊悔亡，聞言不信。 象曰：“其行次且”，位不當也。“聞言不信”，聰不明也。”">​</a></h3><p>一陰在上，眾陽爭趨，三其正應，己獨乘之，故行止皆兇。牽羊者必讓而先之，則為力也易，溺於所趨，必不能用，故曰“聞言不信”，溺於心者，聽必不聰。</p><h3 id="九五-莧陸夬夬-中行無咎。-象曰-中行無咎-中未光也。" tabindex="-1">九五，莧陸夬夬，中行無咎。 象曰：“中行無咎”，中未光也。 <a class="header-anchor" href="#九五-莧陸夬夬-中行無咎。-象曰-中行無咎-中未光也。" aria-label="Permalink to “九五，莧陸夬夬，中行無咎。 象曰：“中行無咎”，中未光也。”">​</a></h3><p>陽近於陰，不能無累，故必正其行然後免咎。</p><h3 id="上六-無號終有兇。-象曰-無號之兇-終不可長也。" tabindex="-1">上六，無號終有兇。 象曰：無號之兇，終不可長也。 <a class="header-anchor" href="#上六-無號終有兇。-象曰-無號之兇-終不可長也。" aria-label="Permalink to “上六，無號終有兇。 象曰：無號之兇，終不可長也。”">​</a></h3>',17)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
